import{_ as l,a0 as u,w as n,s as o,I as t,x as s,a1 as p,A as e,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何在 Kubuntu 21.04 中安装和升级 KDE Plasma 5.22 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kubuntu 21.04 中安装和升级 KDE Plasma 5.22 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kubuntu 21.04 中安装和升级 KDE Plasma 5.22 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kubuntu 21.04 中安装和升级 KDE Plasma 5.22 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210612 How to get KDE Plasma 5.22 in Kubuntu 21.04 Hirsute Hippo","title":"如何在 Kubuntu 21.04 中安装和升级 KDE Plasma 5.22","tag":"202107","desc":""},"relativePath":"202107/20210612 How to get KDE Plasma 5.22 in Kubuntu 21.04 Hirsute Hippo.md","filePath":"[post].md"}'),d={name:"202107/20210612 How to get KDE Plasma 5.22 in Kubuntu 21.04 Hirsute Hippo.md"};function b(g,a,k,m,h,K){const i=u("Link");return n(),o("div",null,[a[21]||(a[21]=t("h1",{id:"如何在-kubuntu-21-04-中安装和升级-kde-plasma-5-22",tabindex:"-1"},[s("如何在 Kubuntu 21.04 中安装和升级 KDE Plasma 5.22 "),t("a",{class:"header-anchor",href:"#如何在-kubuntu-21-04-中安装和升级-kde-plasma-5-22","aria-label":"Permalink to “如何在 Kubuntu 21.04 中安装和升级 KDE Plasma 5.22”"},"​")],-1)),a[22]||(a[22]=t("blockquote",null,[t("p",null,"KDE 团队启用了向后移植 PPA，你可以使用它在 Kubuntu 21.04 Hirsute Hippo 中安装和升级到 KDE Plasma 5.22。")],-1)),a[23]||(a[23]=t("p",null,[t("img",{src:"https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Kubutu-21.04-running-with-KDE-Plasma-5.22-1024x531.jpg",alt:"Kubnutu 21.04 running with KDE Plasma 5.22"})],-1)),t("p",null,[a[1]||(a[1]=s("KDE 团队最近发布了 KDE Plasma 5.22，其中有相当多的增强功能、错误修复以及更新的 KDE 框架和应用版本。这个版本带来了一些改进，如面板的自适应透明度，文件操作弹出时的用户友好通知，“发现”中的软件包类型显示，各种 Wayland 的变化等。在 ",-1)),p(i,{href:"https://www.debugpoint.com/2021/06/kde-plasma-5-22-release/"},{default:e(()=>[...a[0]||(a[0]=[s("这里",-1)])]),_:1}),a[2]||(a[2]=s(" 查看更多关于功能细节。",-1))]),t("p",null,[a[4]||(a[4]=s("如果你正在运行 Kubuntu 21.04 Hirsute Hippo，或者在 ",-1)),p(i,{href:"https://www.debugpoint.com/2021/04/ubuntu-21-04-hirsute-hippo-release/"},{default:e(()=>[...a[3]||(a[3]=[s("Ubuntu 21.04 Hirsute Hippo",-1)])]),_:1}),a[5]||(a[5]=s(" 中安装了自定义的 KDE Plasma，你可以通过以下步骤升级到最新版本。目前的 Hirsute Hippo 系列提供了先前版本 KDE Plasma 5.21.04 与 KDE Framework 5.80。",-1))]),a[24]||(a[24]=r(`<h3 id="在-kubuntu-21-04-hirsute-hippo-中安装-kde-plasma-5-22-的步骤" tabindex="-1">在 Kubuntu 21.04 Hirsute Hippo 中安装 KDE Plasma 5.22 的步骤 <a class="header-anchor" href="#在-kubuntu-21-04-hirsute-hippo-中安装-kde-plasma-5-22-的步骤" aria-label="Permalink to “在 Kubuntu 21.04 Hirsute Hippo 中安装 KDE Plasma 5.22 的步骤”">​</a></h3><p>按照下面的步骤进行。</p><p>如果你想使用图形方法，那么在“发现”中将 <code>ppa:kubuntu-ppa/backports</code> 添加到软件源，然后点击“更新”。</p><p>或者，使用下面的终端方法，以加快安装速度。</p><ul><li><p><strong>步骤 1</strong>：打开一个终端，添加下面的 KDE Backports PPA。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span></code></pre></div></li><li><p><strong>步骤 2</strong>：然后运行以下程序来启动系统升级。这将在你的 Hirsute Hippo 系统中安装最新的 KDE Plasma 5.22。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt full-upgrade</span></span></code></pre></div><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Upgrade-to-Plasma-5.22.jpg" alt="Upgrade to Plasma 5.22"></p></li><li><p><strong>步骤 3</strong>：更新后重新启动，你应该会看到一个更新的 KDE Plasma 5.22 桌面。</p></li></ul><p>考虑到这是整个桌面环境的完整版本升级，安装可能需要一些时间。</p><h3 id="在-ubuntu-21-04-中安装-kde-plasma-5-22" tabindex="-1">在 Ubuntu 21.04 中安装 KDE Plasma 5.22 <a class="header-anchor" href="#在-ubuntu-21-04-中安装-kde-plasma-5-22" aria-label="Permalink to “在 Ubuntu 21.04 中安装 KDE Plasma 5.22”">​</a></h3><p>如果你正在运行基于 GNOME 的默认 Ubuntu 21.04 Hirsute Hippo 桌面，你可以使用这个 PPA 来安装最新的 KDE Plasma。下面是方法。</p><p>打开终端，添加 PPA（像上面的步骤那样）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span></code></pre></div><p>然后，刷新软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>然后运行下面的程序来安装 Kubuntu 桌面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install kubuntu-desktop</span></span></code></pre></div><p>这将在 Ubuntu 21.04 中与 GNOME 一起安装 KDE Plasma 桌面。</p><h3 id="ubuntu-20-04-lts-中的-kde-plasma-5-22" tabindex="-1">Ubuntu 20.04 LTS 中的 KDE Plasma 5.22 <a class="header-anchor" href="#ubuntu-20-04-lts-中的-kde-plasma-5-22" aria-label="Permalink to “Ubuntu 20.04 LTS 中的 KDE Plasma 5.22”">​</a></h3><p>Ubuntu 20.04 LTS 版拥有早期的 KDE Plasma 5.18、KDE Framework 5.68、KDE Applications 19.12.3。所以，在它的整个生命周期中，它不会收到最新的 KDE 更新。所以，从技术上讲，你可以添加上述 PPA 并安装 KDE Plasma 5.22。但我不建议这样做，因为不兼容的软件包、框架可能会导致系统不稳定。</p><p>所以，建议你使用 Kubuntu 21.04 和上面的向后移植 PPA 或者使用 KDE neon 来体验最新的 Plasma 桌面。</p><h3 id="卸载-kde-plasma-5-22" tabindex="-1">卸载 KDE Plasma 5.22 <a class="header-anchor" href="#卸载-kde-plasma-5-22" aria-label="Permalink to “卸载 KDE Plasma 5.22”">​</a></h3><p>如果你改变主意，想回到 KDE Plasma 的原始版本，那么安装 <code>ppa-purge</code> 并清除 PPA。这将使软件包降级，并启用仓库版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ppa-purge</span></span>
<span class="line"><span>sudo ppa-purge ppa:kubuntu-ppa/backports</span></span>
<span class="line"><span>sudo apt update</span></span></code></pre></div><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to “结束语”">​</a></h3><p>我希望这个快速指南能帮助你在 Kubuntu 21.04 Hirsute Hippo 中安装最新的 KDE Plasma 5.22。这可以让你体验到最新的 KDE 技术以及 KDE 框架和应用。然而，你应该知道，并不是所有的功能都应该在向后移植 PPA 中提供，它只有选定的功能和错误修复，这才能通过回归测试并安全使用。也就是说，你总是可以把 KDE Neon 安装成一个全新的系统来享受 KDE 的最新技术。</p><hr>`,24)),t("p",null,[a[7]||(a[7]=s("via: ",-1)),p(i,{href:"https://www.debugpoint.com/2021/06/plasma-5-22-kubuntu-21-04/"},{default:e(()=>[...a[6]||(a[6]=[s("https://www.debugpoint.com/2021/06/plasma-5-22-kubuntu-21-04/",-1)])]),_:1})]),t("p",null,[a[12]||(a[12]=s("作者：",-1)),p(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...a[8]||(a[8]=[s("Arindam",-1)])]),_:1}),a[13]||(a[13]=s(" 选题：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[14]||(a[14]=s(" 译者：",-1)),p(i,{href:"https://github.com/geekpi"},{default:e(()=>[...a[10]||(a[10]=[s("geekpi",-1)])]),_:1}),a[15]||(a[15]=s(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:e(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[18]||(a[18]=s("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[16]||(a[16]=[s("LCTT",-1)])]),_:1}),a[19]||(a[19]=s(" 原创编译，",-1)),p(i,{href:"https://linux.cn/"},{default:e(()=>[...a[17]||(a[17]=[s("Linux中国",-1)])]),_:1}),a[20]||(a[20]=s(" 荣誉推出",-1))])])}const E=l(d,[["render",b]]);export{D as __pageData,E as default};
